tool_input.command:
$root="$env:USERPROFILE\.openviking"
Write-Output "=== ov.conf JSON validity ==="
try { $j = Get-Content "$root\ov.conf" -Raw | ConvertFrom-Json; Write-Output "JSON OK"; Write-Output ("retrieval: enable_intent=" + $j.retrieval.enable_intent + " timeout=" + $j.retrieval.recall_intent_timeout_s) } catch { Write-Output "JSON INVALID: $_" }

function Do-Search($sid){
  $obj = @{ query="openviking 看门狗 进程掉线"; limit=3; mode="list" }
  if($sid){ $obj.session_id=$sid }
  $json = $obj | ConvertTo-Json -Compress
  $sw=[System.Diagnostics.Stopwatch]::StartNew()
  try{
    $r=Invoke-WebRequest -Uri "http://127.0.0.1:1933/api/v1/search/search" -Method POST -Body ([System.Text.Encoding]::UTF8.GetBytes($json)) -ContentType "application/json; charset=utf-8" -UseBasicParsing -TimeoutSec 60
    $sw.Stop(); Write-Output ("sid=" + $(if($sid){$sid}else{"none"}) + " status=" + $r.StatusCode + " ms=" + [math]::Round($sw.ElapsedMilliseconds))
  }catch{ $sw.Stop(); Write-Output ("sid=" + $(if($sid){$sid}else{"none"}) + " ERR ms=" + [math]::Round($sw.ElapsedMilliseconds) + " " + $_.Exception.Message)
    if($_.Exception.Response){ $sr=New-Object System.IO.StreamReader($_.Exception.Response.GetResponseStream()); Write-Output ("  body: " + $sr.ReadToEnd()) } }
}
Write-Output "=== no-session search ==="; Do-Search $null
Write-Output "=== with a fresh session ==="
$s = Invoke-WebRequest -Uri "http://127.0.0.1:1933/api/v1/sessions" -Method POST -Body ([System.Text.Encoding]::UTF8.GetBytes('{"session_id":"ovverify-test-1"}')) -ContentType "application/json" -UseBasicParsing -TimeoutSec 15 -ErrorAction SilentlyContinue
Write-Output ("create session: " + $s.StatusCode)
Do-Search "ovverify-test-1"
